# Generated by manage.py generate_test_cases.
"""Regression scenarios for non-destructive week-date replacement."""

from django.db import models

from bloomerp.form_behaviors.builtins.populate_week_dates import POPULATE_WEEK_DATES
from bloomerp.form_behaviors.definition import (
    BehaviorContext,
    BehaviorResult,
    FieldValueUpdate,
)
from bloomerp.form_behaviors.shared.write_policy import WritePolicyField
from bloomerp.model_fields.week_field import WeekField
from bloomerp.tests.base import (
    BehaviorActionScenario,
    BloomerpBehaviorActionTestCase,
)
from bloomerp.tests.utils.dynamic_models import create_test_models


class TestPopulateWeekDatesAction(BloomerpBehaviorActionTestCase):
    """Ensure replace updates one date column without rebuilding existing rows."""

    action = POPULATE_WEEK_DATES
    auto_create_customers = False
    schedule_model: type[models.Model]
    line_model: type[models.Model]

    @classmethod
    def setUpClass(cls) -> None:
        """Create a week source and dated one-to-many target."""
        super().setUpClass()
        fixtures = create_test_models(
            "bloomerp",
            {
                "BehaviorWeekSchedule": {
                    "name": models.CharField(max_length=40),
                    "week": WeekField(max_length=8),
                },
                "BehaviorWeekScheduleLine": {
                    "schedule": models.ForeignKey(
                        "bloomerp.BehaviorWeekSchedule",
                        on_delete=models.CASCADE,
                        related_name="lines",
                    ),
                    "planned_date": models.DateField(null=True, blank=True),
                    "note": models.CharField(max_length=40, blank=True),
                },
            },
            use_bloomerp_base=True,
        )
        cls.schedule_model = fixtures["BehaviorWeekSchedule"]
        cls.line_model = fixtures["BehaviorWeekScheduleLine"]

    def _scenario(
        self,
        name: str,
        rows: list[dict[str, object]],
        expected: list[dict[str, object]] | None,
        *,
        days: int = 5,
        write_policy: str = "replace",
    ) -> BehaviorActionScenario:
        """Build one generated action scenario around ISO week 2026-W38."""
        listener = self.get_application_field("week", self.schedule_model)
        target = self.get_application_field("lines", self.schedule_model)
        result = (
            BehaviorResult()
            if expected is None
            else BehaviorResult(
                values=(
                    FieldValueUpdate(
                        field="lines",
                        value=expected,
                    ),
                )
            )
        )
        return BehaviorActionScenario(
            name=name,
            context=BehaviorContext(
                values={"week": "2026-W38", "lines": rows},
                listener_field="week",
                target_field="lines",
            ),
            listener=listener,
            target=target,
            config={
                "write_policy": write_policy,
                "source": "week",
                "column": "planned_date",
                "days": days,
            },
            expected_result=result,
        )

    def get_test_scenarios(self) -> list[BehaviorActionScenario]:
        """Cover fewer, equal, and extra active rows plus if-empty behavior."""
        dates = [
            "2026-09-14",
            "2026-09-15",
            "2026-09-16",
            "2026-09-17",
            "2026-09-18",
        ]
        fewer = [
            {
                "id": "line-1",
                "planned_date": "2020-01-01",
                "note": "Keep one",
                "metadata": {"tags": ["a", "b"]},
            },
            {
                "id": "line-deleted",
                "planned_date": "2019-01-01",
                "note": "Deleted stays exact",
                "DELETE": True,
            },
            {
                "id": "line-2",
                "planned_date": None,
                "note": "Keep two",
                "choices": ["x", "y"],
            },
        ]
        fewer_expected = [
            {**fewer[0], "planned_date": dates[0]},
            fewer[1],
            {**fewer[2], "planned_date": dates[1]},
            {"planned_date": dates[2]},
            {"planned_date": dates[3]},
            {"planned_date": dates[4]},
        ]
        equal = [
            {"id": f"line-{index}", "planned_date": value, "note": "Keep"}
            for index, value in enumerate(dates, start=1)
        ]
        more = [
            {
                "id": f"line-{index}",
                "planned_date": "2020-01-01",
                "note": f"Keep {index}",
            }
            for index in range(1, 8)
        ]
        more_expected = [
            {
                **row,
                "planned_date": dates[index] if index < 5 else None,
            }
            for index, row in enumerate(more)
        ]
        return [
            self._scenario(
                "Replace preserves rows and appends missing generated dates",
                fewer,
                fewer_expected,
            ),
            self._scenario(
                "Replace returns no update when equal active rows are current",
                equal,
                None,
            ),
            self._scenario(
                "Replace preserves extra rows and clears only extra date cells",
                more,
                more_expected,
            ),
            self._scenario(
                "If-empty preserves the established nonempty collection behavior",
                fewer,
                None,
                write_policy="if_empty",
            ),
            self._scenario(
                "If-empty populates an empty collection",
                [],
                [{"planned_date": value} for value in dates],
                write_policy="if_empty",
            ),
        ]

    def test_write_policy_uses_shared_subset_and_legacy_default(self) -> None:
        """Week population shares only empty and collection-replace policies."""
        target = self.get_application_field("lines", self.schedule_model)
        form_class = self.action.config_form_factory(target, None)
        field = form_class.base_fields["write_policy"]
        self.assertIsInstance(field, WritePolicyField)
        self.assertEqual(
            [choice[0] for choice in field.choices], ["if_empty", "replace"]
        )
        self.assertEqual(field.clean(""), "if_empty")
